def validate_task_order(n, edges, order):
    if len(order) != n:
        return False
    pos = {}
    for i, task in enumerate(order):
        if task < 0 or task >= n or task in pos:
            return False
        pos[task] = i
    if len(pos) != n:
        return False
    for a, b in edges:
        if pos[a] >= pos[b]:
            return False
    return True
